729	    protected Object deserializeWithUnwrapped(JsonParser p, DeserializationContext ctxt)
730	        throws IOException
731	    {
732	        if (_delegateDeserializer != null) {
733	            return _valueInstantiator.createUsingDelegate(ctxt, _delegateDeserializer.deserialize(p, ctxt));
734	        }
735	        if (_propertyBasedCreator != null) {
736	            return deserializeUsingPropertyBasedWithUnwrapped(p, ctxt);
737	        }
738	        TokenBuffer tokens = ctxt.bufferForInputBuffering(p);
739	        tokens.writeStartObject();
740	        final Object bean = _valueInstantiator.createUsingDefault(ctxt);
741	
742	        // [databind#631]: Assign current value, to be accessible by custom serializers
743	        p.assignCurrentValue(bean);
744	
745	        if (_injectables != null) {
746	            injectValues(ctxt, bean);
747	        }
748	        final Class<?> activeView = _needViewProcesing ? ctxt.getActiveView() : null;
749	        String propName = p.hasTokenId(JsonTokenId.ID_FIELD_NAME) ? p.currentName() : null;
750	
751	        for (; propName != null; propName = p.nextFieldName()) {
752	            p.nextToken();
753	            SettableBeanProperty prop = _beanProperties.find(propName);
754	            if (prop != null) { // normal case
755	                if ((activeView != null) && !prop.visibleInView(activeView)) {
756	                    p.skipChildren();
757	                    continue;
758	                }
759	                try {
760	                    prop.deserializeAndSet(p, ctxt, bean);
761	                } catch (Exception e) {
762	                    wrapAndThrow(e, bean, propName, ctxt);
763	                }
764	                continue;
765	            }
766	            // Things marked as ignorable should not be passed to any setter
767	            if (IgnorePropertiesUtil.shouldIgnore(propName, _ignorableProps, _includableProps)) {
768	                handleIgnoredProperty(p, ctxt, bean, propName);
769	                continue;
770	            }
771	            // 29-Nov-2016, tatu: probably should try to avoid sending content
772	            //    both to any setter AND buffer... but, for now, the only thing
773	            //    we can do.
774	            // how about any setter? We'll get copies but...
775	            if (_anySetter == null) {
776	                // but... others should be passed to unwrapped property deserializers
777	                tokens.writeFieldName(propName);
778	                tokens.copyCurrentStructure(p);
779	                continue;
780	            }
781	            // Need to copy to a separate buffer first
782	            TokenBuffer b2 = ctxt.bufferAsCopyOfValue(p);
783	            tokens.writeFieldName(propName);
784	            tokens.append(b2);
785	            try {
786	                _anySetter.deserializeAndSet(b2.asParserOnFirstToken(), ctxt, bean, propName);
787	            } catch (Exception e) {
788	                wrapAndThrow(e, bean, propName, ctxt);
789	            }
790	        }
791	        tokens.writeEndObject();
792	        _unwrappedPropertyHandler.processUnwrapped(p, ctxt, bean, tokens);
793	        return bean;
